func ListSBAdPreviewTemplate(value string) []SBAdPreviewTemplate {
	switch value {
	case constants.SBTypeProductCollection:
		return ListSBAdPreviewProductCollection()
	case constants.SBTypeStoreSpotlight:
		return ListSBAdPreviewStoreSpotlight()
	case constants.SBTypeVideo:
		return ListSBAdPreviewVideo()
	case constants.SBTypeVideoStore:
		return ListSBAdPreviewVideoStore()
	default:
		return []SBAdPreviewTemplate{}
	}
}

func ListSBAdPreviewProductCollection() []SBAdPreviewTemplate {
	return []SBAdPreviewTemplate{TETRIS_MWEB_SPARKLE_PRODUCT_COLLECTION(), TETRIS_MWEB_3PSL_PRODUCT_COLLECTION(),
		TETRIS_DESKTOP_SPARKLE_PRODUCT_COLLECTION(), TETRIS_DESKTOP_3PSL_PRODUCT_COLLECTION()}
}
func ListSBAdPreviewStoreSpotlight() []SBAdPreviewTemplate {
	return []SBAdPreviewTemplate{TETRIS_MWEB_SPARKLE_STORE_SPOTLIGHT(), TETRIS_MWEB_3PSL_STORE_SPOTLIGHT(),
		TETRIS_DESKTOP_SPARKLE_STORE_SPOTLIGHT(), TETRIS_DESKTOP_3PSL_STORE_SPOTLIGHT()}
}

func ListSBAdPreviewVideo() []SBAdPreviewTemplate {
	return []SBAdPreviewTemplate{TETRIS_VIDEO_SINGLE_MEDIA(), TETRIS_VIDEO_SINGLE_MEDIA_DESKTOP()}
}

func ListSBAdPreviewVideoStore() []SBAdPreviewTemplate {
	return []SBAdPreviewTemplate{TETRIS_MWEB_SPARKLE(), TETRIS_VIDEO_SINGLE_MEDIA_STORE(), TETRIS_DESKTOP_SPARKLE(),
		TETRIS_VIDEO_SINGLE_MEDIA_DESKTOP_STORE()}
}
